// Java types generated by Smithy Java from the model in ../../contract: request
// and response types, errors and their schemas. Routing and the API Gateway
// glue are written by hand.

plugins {
    `java-library`
    alias(libs.plugins.smithy.base)
}

// The model's traits (restJson1, protocol tests, ValidationException). The Smithy plugin loads
// the model from this project's own classpaths, but the generated code doesn't use these jars,
// and smithy-validation-model drags in all of smithy-cli. A private configuration keeps them off
// what other projects (and the Lambda package) get from this one.
val smithyModels = configurations.create("smithyModels")
configurations.compileClasspath { extendsFrom(smithyModels) }
configurations.runtimeClasspath { extendsFrom(smithyModels) }
configurations.testCompileClasspath { extendsFrom(smithyModels) }
configurations.testRuntimeClasspath { extendsFrom(smithyModels) }

dependencies {
    smithyBuild(libs.smithy.java.codegen)
    smithyModels(libs.smithy.aws.traits)
    smithyModels(libs.smithy.protocol.test.traits)
    smithyModels(libs.smithy.validation.model)

    api(libs.smithy.java.core)
    api(libs.smithy.java.json)
    api(libs.smithy.java.framework.errors)
}

tasks.test {
    systemProperty("cloudprnt.contract.model", file("../../contract/model").absolutePath)
}

smithy {
    // The model lives in ../../contract.
    format = false
}

// Two generated trees: the CloudPRNT protocol (the source projection) and the
// print-job API (the "api" projection). Each registers its GeneratedSchemaIndex
// in the same META-INF/services file, so the two files are merged.
val schemaIndexService = "META-INF/services/software.amazon.smithy.java.core.schema.SchemaIndex"
val mergedResources = layout.buildDirectory.dir("generated/merged-resources")

afterEvaluate {
    val generated = listOf(smithy.sourceProjection.get(), "api").map {
        smithy.getPluginProjectionPath(it, "java-codegen").get()
    }
    val mergeSchemaIndexes = tasks.register("mergeSchemaIndexes") {
        dependsOn(tasks.named("smithyBuild"))
        val inputs = generated.map { file("$it/resources/$schemaIndexService") }
        val output = mergedResources.map { it.file(schemaIndexService) }
        this.inputs.files(inputs)
        outputs.file(output)
        doLast {
            val lines = inputs.flatMap { it.readLines() }.map { it.trim() }.filter { it.isNotEmpty() }
            check(lines.size == inputs.size) { "expected one SchemaIndex per projection: $lines" }
            output.get().asFile.apply { parentFile.mkdirs() }.writeText(lines.joinToString("\n", postfix = "\n"))
        }
    }
    sourceSets {
        main {
            java {
                generated.forEach { srcDir("$it/java") }
            }
            resources {
                generated.forEach { srcDir("$it/resources") }
                srcDir(mergedResources)
                exclude { it.file.path.contains("/smithyprojections/") && it.path == schemaIndexService }
            }
        }
    }
    tasks.processResources { dependsOn(mergeSchemaIndexes) }
}

tasks.processResources { dependsOn(tasks.named("smithyBuild")) }

tasks.compileJava {
    dependsOn(tasks.named("smithyBuild"))
    // Generated code isn't held to our lint settings.
    options.compilerArgs.removeAll { it.startsWith("-Xlint") }
}

// Checkstyle and Spotless check only hand-written code (src/), and coverage
// only counts hand-written classes: everything here is generated.
tasks.named<Checkstyle>("checkstyleMain") { enabled = false }
tasks.named<JacocoCoverageVerification>("jacocoCoverage") { enabled = false }
